CREATE DATABASE yyspxtdb;
USE yyspxtdb;

SET FOREIGN_KEY_CHECKS=0;

-- ----------------------------
-- Table structure for admin
-- ----------------------------
DROP TABLE IF EXISTS `admin`;
CREATE TABLE `admin` (
  `user` varchar(20) DEFAULT NULL,
  `password` varchar(20) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of admin
-- ----------------------------

-- ----------------------------
-- Table structure for filmarrangement
-- ----------------------------
DROP TABLE IF EXISTS `filmarrangement`;
CREATE TABLE `filmarrangement` (
  `rownumber` int(11) NOT NULL,
  `screeningroom` varchar(10) NOT NULL,
  `movieid` int(11) NOT NULL AUTO_INCREMENT,
  `Showtime` date DEFAULT NULL,
  `Showtimes` time DEFAULT NULL,
  PRIMARY KEY (`rownumber`),
  KEY `order_ibfk_1` (`movieid`),
  KEY `Showtime` (`Showtime`),
  KEY `Showtimes` (`Showtimes`),
  KEY `screeningroom` (`screeningroom`),
  CONSTRAINT `order_ibfk_1` FOREIGN KEY (`movieid`) REFERENCES `movie` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of filmarrangement
-- ----------------------------

-- ----------------------------
-- Table structure for movie
-- ----------------------------
DROP TABLE IF EXISTS `movie`;
CREATE TABLE `movie` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(30) NOT NULL,
  `img` longblob,
  `hot` double(10,2) DEFAULT NULL,
  `director` varchar(30) DEFAULT NULL,
  `actorid` varchar(50) DEFAULT NULL,
  `startdate` date DEFAULT NULL,
  `enddate` date DEFAULT NULL,
  `Movieduration` int(11) DEFAULT NULL,
  `fare` double(10,2) DEFAULT NULL,
  `Moviegenre` varchar(50) DEFAULT NULL,
  `country` varchar(50) DEFAULT NULL,
  `synopsis` text,
  `score` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of movie
-- ----------------------------

-- ----------------------------
-- Table structure for odrseat
-- ----------------------------
DROP TABLE IF EXISTS `odrseat`;
CREATE TABLE `odrseat` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `line` int(11) DEFAULT NULL,
  `row` int(11) DEFAULT NULL,
  `ordernumber` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ordernumber` (`ordernumber`),
  CONSTRAINT `odrseat_ibfk_1` FOREIGN KEY (`ordernumber`) REFERENCES `orders` (`Ordernum`)
) ENGINE=InnoDB AUTO_INCREMENT=125 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of odrseat
-- ----------------------------

-- ----------------------------
-- Table structure for orders
-- ----------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `movieid` int(11) NOT NULL,
  `Ordernum` int(50) NOT NULL,
  `showtime` date DEFAULT NULL,
  `showtimes` time DEFAULT NULL,
  `seatnum` varchar(10) DEFAULT NULL,
  `Screeningroom` varchar(10) DEFAULT NULL,
  `user` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`Ordernum`),
  KEY `movie` (`movieid`) USING BTREE,
  KEY `showtime` (`showtime`),
  KEY `showtimes` (`showtimes`),
  KEY `user` (`user`),
  KEY `Screeningroom` (`Screeningroom`),
  CONSTRAINT `orders_ibfk_1` FOREIGN KEY (`movieid`) REFERENCES `movie` (`id`),
  CONSTRAINT `orders_ibfk_2` FOREIGN KEY (`showtime`) REFERENCES `filmarrangement` (`Showtime`),
  CONSTRAINT `orders_ibfk_3` FOREIGN KEY (`showtimes`) REFERENCES `filmarrangement` (`Showtimes`),
  CONSTRAINT `orders_ibfk_5` FOREIGN KEY (`user`) REFERENCES `public` (`user`),
  CONSTRAINT `orders_ibfk_6` FOREIGN KEY (`Screeningroom`) REFERENCES `filmarrangement` (`screeningroom`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of orders
-- ----------------------------

-- ----------------------------
-- Table structure for public
-- ----------------------------
DROP TABLE IF EXISTS `public`;
CREATE TABLE `public` (
  `user` varchar(20) NOT NULL,
  `password` varchar(20) DEFAULT NULL,
  `name` varchar(50) DEFAULT 'user123',
  `sex` char(1) DEFAULT '男',
  `birthday` date DEFAULT '2023-05-25',
  `Signature` char(50) DEFAULT '这个人很懒，什么都没有留下',
  PRIMARY KEY (`user`),
  KEY `user` (`user`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of public
-- ----------------------------

-- ----------------------------
-- Table structure for seat
-- ----------------------------
DROP TABLE IF EXISTS `seat`;
CREATE TABLE `seat` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `line` int(10) DEFAULT NULL,
  `row` int(10) DEFAULT NULL,
  `flag` int(1) DEFAULT NULL,
  `rownumber` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `seat_ibfk_1` (`rownumber`),
  CONSTRAINT `seat_ibfk_1` FOREIGN KEY (`rownumber`) REFERENCES `filmarrangement` (`rownumber`)
) ENGINE=InnoDB AUTO_INCREMENT=902 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of seat
-- ----------------------------
